contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We deposit some Ether into c under this contract's address, then call withdrawAll.
    // If withdrawAll does not revert, then calling withdrawAll a second time (without depositing more)
    // must not transfer any additional Ether to this contract (i.e., it must either revert or transfer zero).
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "insufficient balance for test");

        // Deposit 'amount' into c for this contract's credit
        c.deposit{value: amount}(); if (__ESBMC_reverted()) return;

        // Try first withdrawal and record whether it reverted
        bool firstReverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstReverted = true;
        } else {
            firstReverted = false;
        }

        // Record balances after first attempt
        uint balThisAfterFirst = address(this).balance;
        uint balCAfterFirst = address(c).balance;

        // Try second withdrawal and record whether it reverted and balances after
        bool secondReverted;
        c.withdrawAll(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }

        uint balThisAfterSecond = address(this).balance;
        uint balCAfterSecond = address(c).balance;

        // General rule: If the first withdraw did not revert, then the second withdraw cannot successfully transfer any additional Ether to this contract.
        // That is, either the second withdraw reverted, or it succeeded but did not increase this contract's balance.
        assert(firstReverted || secondReverted || balThisAfterSecond <= balThisAfterFirst);
    }

    // Allow receiving Ether when c sends funds back
    receive() external payable {}
}

